}

/** Like transfer, but moving 0 is allowed and does nothing. Same account is always refused. */
export function move(c: C, from: Account, to: Account, amount: number): void {
  if (amount < 0) refuse({ kind: "BadAmount" });
  if (from === to) refuse({ kind: "SameAccount" });
  if (amount > 0) transfer(c, from, to, amount);
}
```

**2. `escrow.ts` — `tip`.** Change `move(c, buyer, seller, amount);` to `moveAllowingSameZero(c, buyer, seller, amount);`. `tip` calls `move`, so without this, `tip(A, A, 0)` would start refusing instead of succeeding and emitting `Tipped`. That would break the "every other operation unchanged" rule. The other places that call `move` (`capture`, `refund`, `split`) already refuse same-account inputs before reaching it, so they behave the same either way.

